 "content": "def transform(grid):
    # Reconstruct occluded grid by its 6x6-ish local wallpaper using the
    # visible matching row/column pattern in the surrounding repeated design.
    # Use modular 2D pattern correlation against all visible cells.
    h=len(grid); w=len(grid[0]); out=[r[:] for r in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=6: continue
            scores={}
            for dr in range(-15,16):
                for dc in range(-15,16):
                    rr=(r+dr)%h; cc=(c+dc)%w
                    if grid[rr][cc]==6: continue
                    # Estimate motif translational relation with same offset
                    score=0
                    for y in range(max(0,r-3),min(h,r+4)):
                        for x in range(max(0,c-3),min(w,c+4)):
                            yy=(y+dr)%h; xx=(x+dc)%w
                            if grid[y][x]!=6 and grid[yy][xx]==grid[y][x]: score+=1
                    scores.setdefault(grid[rr][cc],0); scores[grid[rr][cc]]=max(scores[grid[rr][cc]],score)
            if scores: out[r][c]=max(scores,key=scores.get)
    return out
